#include <bits/stdc++.h>
using namespace std;
#define ll long long
#define vll vector<ll>
int main() {
	int tc;cin>>tc;
	while(tc--){
	    int n;cin>>n;
	    int m=3*n;
	    vll a(m);
	    for(auto &x:a) cin>>x;
	    sort(a.begin(),a.end());
	    reverse(a.begin(),a.end());
	    ll score=0;
	    for(int i=0;i<2*n;i++){
	        score+=4*a[i];
	    }
	   // cout<<score<<endl;
	    ll ans=score;
	    ll single=0,paired=n,trip=0;
	    while(1){
	        while(paired>0){
	            int id1=single+2*paired;
	            int id2=3*n-2*single-paired;
	            ll newsc=1ll*score-a[id1-2]-a[id1-1]+3ll*a[id2];
	            if(newsc<score) break;
	                paired--;
	                trip++;
	                score=newsc;
	        }
	        ans=max(ans,score);
	        if(single==n) break;
	        if(trip==0){
	            int id1=single+2*paired;
	            int id2=3*n-2*single-paired;
	            score+=3*a[id2]-a[id1-1]-a[id1-2];
	            trip++;
	            paired--;
	        }
	        int id2=single+2*paired;
	        int id1=3*n-2*single-paired;
	        score+=2*a[single]+a[id2]-3*a[id1-1]-3*a[id1-2];
	        single++;
	        trip--;
	    }
	    cout<<ans<<endl;
	}
}
